# Technical section: naive review's full deciding table (P2-T3.df1, verdicts as symbols) and the two results fixed by
# construction (P2-T3.df4), moved here by entry 6; and the forest graph P2-F9.
show = ["result_id", "comparison", "team", "capacity_label", "measure", "estimate (mean of 5)", "adjusted interval", "seed range", "versions 1 to 5",
        "verdict_mean_of_5", "verdict", "verdict_route", "labels", "reviewed_part_point", "unreviewed_part_point",
        "overall_false_rejection_rate_team", "overall_false_rejection_rate_policy_1"]
main = T3[T3["verdict_route"] != "P2-K"].copy()
for c in ("verdict", "verdict_mean_of_5"):
    main[c] = L.symbols(main[c], deciding=(c == "verdict"))
main["versions 1 to 5"] = [" / ".join(str(L.symbol(x)) for x in s_.split(" / ")) for s_ in main["versions 1 to 5"]]
V.show(main[show], 'P2-T3.df1', hide=['result_id'], rename={'capacity_label': 'capacity', 'estimate (mean of 5)': 'difference (average of the five versions)', 'adjusted interval': 'widened range (deciding)', 'seed range': 'range over the five random orders', 'versions 1 to 5': 'verdicts of versions 1 to 5', 'verdict_mean_of_5': 'verdict of the average of the five', 'verdict_route': 'how the verdict was reached', 'labels': 'note', 'reviewed_part_point': 'part from the reviewed alerts (point figure)', 'unreviewed_part_point': 'part from the alerts beyond capacity (point figure)', 'overall_false_rejection_rate_team': 'overall false rejection rate, team', 'overall_false_rejection_rate_policy_1': 'overall false rejection rate, full automation'}, index_names={}, column_names={}, values={'comparison': {'1': 'team A at full capacity against full automation', '2': 'team B against full automation', '3': 'team C against full automation', '4': 'team B against team A, both at capacity 0.75', '5': 'team C against team A, both at capacity 0.75'}, 'verdict_route': {'all five versions': 'all five versions agree', 'mean of the five versions': 'average of the five'}}, index={}, cells=[], empty_cells=True)
V.md('P2-T3.caption-construction', "**Team C against team A, both at capacity 0.75: the two results fixed by construction** (they follow from team C's rule and are not findings)", {}, label=L.L_P2K)
V.show(T3[T3["verdict_route"] == "P2-K"].assign(verdict=lambda x: L.symbols(x["verdict"], deciding=True))[["result_id", "team", "capacity_label", "measure", "estimate (mean of 5)", "adjusted interval", "versions 1 to 5", "verdict", "label"]], 'P2-T3.df4', hide=['result_id'], rename={'capacity_label': 'capacity', 'estimate (mean of 5)': 'difference (average of the five versions)', 'adjusted interval': 'widened range (deciding)', 'versions 1 to 5': 'verdicts of versions 1 to 5', 'label': 'note'}, index_names={}, column_names={}, values={'label': {'Fixed by construction (P2-K); not a finding.': "by construction (set by team C's rule); not a finding"}}, index={}, cells=[], empty_cells=True)
forest(T3[T3["verdict_route"] != "P2-K"], 'Naive review: the 61 results that decide, with their widened ranges (square: average of the five versions; dots: the five versions)', "P2-F9_forest.png", ('forest.row-p2', '{comparison}, capacity {capacity}: {verdict}', {'comparison': {'1': 'team A against full automation', '2': 'team B against full automation', '3': 'team C against full automation', '4': 'team B against team A', '5': 'team C against team A'}}))
